entries.syntax:
abstract aligned(8) class SampleEntry (unsigned int(32) format) extends Box(format){
	const unsigned int(8)[6] reservedSampleEntry = 0;
	unsigned int(16) data_reference_index;
}

aligned(8) class SegmentIndexBox extends FullBox('sidx', version, 0) {
	unsigned int(32) reference_ID;
	unsigned int(32) timescale;
	if (version==0) {
		unsigned int(32) earliest_presentation_time;
		unsigned int(32) first_offset;
	}
	else {
		unsigned int(64) earliest_presentation_time;
		unsigned int(64) first_offset;
	}
	unsigned int(16) reserved = 0;
	unsigned int(16) reference_count;
	for(i=1; i <= reference_count; i++)
	{
		bit(1)   reference_type;
		unsigned int(31) referenced_size;
		unsigned int(32) subsegment_duration;
		bit(1)    starts_with_SAP;
		unsigned int(3) SAP_type;
		unsigned int(28) SAP_delta_time;
	}
}

aligned(8) class DataEntryBaseBox(entry_type, bit(24) flags)
	extends FullBox(entry_type, version = 0, flags) {

}

aligned(8) class SubsegmentIndexBox extends FullBox('ssix', 0, 0) {
	unsigned int(32) subsegment_count;
	for( i=1; i <= subsegment_count; i++)
	{
		unsigned int(32) range_count;
		for ( j=1; j <= range_count; j++) {
			unsigned int(8) level;
			unsigned int(24) range_size;
		}
	}
}

class ReceivedRtcpHintSampleEntry() extends HintSampleEntry ('rtcp') {
	uint(16)		hinttrackversion = 1;
	uint(16)		highestcompatibleversion = 1;
	uint(32)		maxpacketsize;
}

aligned(8) class SampleAuxiliaryInformationSizesBox
	extends FullBox('saiz', version, flags)
{
	if(version == 0) {
		if (flags & 1) {
			unsigned int(32) aux_info_type;
			unsigned int(32) aux_info_type_parameter;
		}
		unsigned int(8) default_sample_info_size;
		unsigned int(32) sample_count;
		if (default_sample_info_size == 0) {
			unsigned int(8) sample_info_size[ sample_count ];
		}
	}
	else if(version == 1) {
		if (flags & 1) {
			unsigned int(32) aux_info_type;
			unsigned int(32) aux_info_type_parameter;
		}
		unsigned int(16) default_sample_info_size;
		unsigned int(32) sample_count;
		if (default_sample_info_size == 0) {
			unsigned int(16) sample_info_size[ sample_count ];
		}
	}
	else if(version == 2) {
		if (flags & 1) {
			unsigned int(32) aux_info_type;
			unsigned int(32) aux_info_type_parameter;
		}
		unsigned int(32) default_sample_info_size;
		unsigned int(32) sample_count;
		if (default_sample_info_size == 0) {
			unsigned int(32) sample_info_size[ sample_count ];
		}
	}
}
